package com.veyra.partner;
import com.veyra.security.CurrentUser;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/partner") public class PartnerController{private final JdbcTemplate db;public PartnerController(JdbcTemplate d){db=d;}public record Org(String name,String partnerType,String billingEmail){}public record Guest(String fullName,String phone,String email,String externalReference){}
 @PostMapping("/organizations")ResponseEntity<Map<String,UUID>>org(@RequestBody Org r){UUID id=UUID.randomUUID();db.update("insert into partner_organizations(id,name,partner_type,status,billing_email) values (?,?,?,'SUBMITTED',?)",id,r.name(),r.partnerType(),r.billingEmail());db.update("insert into partner_users(partner_id,user_id,partner_role) values (?,?,'PARTNER_OWNER')",id,CurrentUser.id());db.update("insert into user_roles(user_id,role_id) select ?,id from roles where code='PARTNER_OWNER' on conflict do nothing",CurrentUser.id());return ResponseEntity.status(201).body(Map.of("partnerId",id));}
 @PostMapping("/{p}/beneficiaries")ResponseEntity<Map<String,UUID>>guest(@PathVariable UUID p,@RequestBody Guest g){member(p);UUID id=UUID.randomUUID();db.update("insert into partner_beneficiaries(id,partner_id,full_name,phone,email,external_reference) values (?,?,?,?,?,?)",id,p,g.fullName(),g.phone(),g.email(),g.externalReference());return ResponseEntity.status(201).body(Map.of("beneficiaryId",id));}
 @GetMapping("/{p}/finance")Map<String,Object>finance(@PathVariable UUID p){member(p);return db.queryForMap("select po.credit_status,po.credit_limit_minor,coalesce(pia.outstanding_minor,0) outstanding_minor,coalesce(pia.overdue_minor,0) overdue_minor from partner_organizations po left join partner_invoice_accounts pia on pia.partner_id=po.id where po.id=?",p);}
 private void member(UUID p){if(db.queryForObject("select count(*) from partner_users where partner_id=? and user_id=?",Integer.class,p,CurrentUser.id())==0)throw new org.springframework.security.access.AccessDeniedException("partner");}
}